// Widths generated by scripts/build-images.sh.
const WIDTHS = [400, 800, 1200, 1600] as const

export type PhotoCategory = 'Landscape' | 'Wildlife'

export const CATEGORIES = ['All', 'Landscape', 'Wildlife'] as const
export type CategoryFilter = (typeof CATEGORIES)[number]

export type Photo = {
  base: string
  caption: string
  /** Named place, only when the existing record already states one. */
  place?: string
  /** Drawn from the site's own "Landscape & Wildlife" split. */
  category: PhotoCategory
  alt: string
  /** Intrinsic size of the largest derivative, so the img carries a real ratio. */
  width: number
  height: number
}

export const PHOTOS: readonly Photo[] = [
  {
    base: 'CaliforniaSkyline',
    caption: 'Ridgelines',
    place: 'California',
    category: 'Landscape',
    alt: 'Layered California ridgelines receding into a haze-filled valley under a pale sky',
    width: 1600,
    height: 1067,
  },
  {
    base: 'CuriousFox',
    caption: 'Curious Fox',
    category: 'Wildlife',
    alt: 'A fox sitting on a dirt bank amid tall grass in low light, looking directly at the camera',
    width: 1600,
    height: 1065,
  },
  {
    base: 'BlackAndWhiteBoat',
    caption: 'Moored',
    category: 'Landscape',
    alt: 'Black and white photograph of a small fishing boat moored beside a weathered wooden pier on flat, still water, with low islands on the horizon',
    width: 1600,
    height: 1067,
  },
]

const srcSet = (base: string, ext: string) =>
  WIDTHS.map((w) => `/images/${base}-${w}.${ext} ${w}w`).join(', ')

export function PhotoImage({
  photo,
  sizes,
  loading = 'lazy',
  className = 'block h-auto w-full',
  vtName,
}: {
  photo: Photo
  sizes: string
  loading?: 'eager' | 'lazy'
  className?: string
  /** View Transition name, so a photograph can move from the grid into the viewer. */
  vtName?: string
}) {
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet(photo.base, 'avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(photo.base, 'webp')} sizes={sizes} />
      <img
        src={`/images/${photo.base}-800.webp`}
        srcSet={srcSet(photo.base, 'webp')}
        sizes={sizes}
        alt={photo.alt}
        width={photo.width}
        height={photo.height}
        loading={loading}
        decoding="async"
        className={className}
        style={vtName ? { viewTransitionName: vtName } : undefined}
      />
    </picture>
  )
}
